mapper.select:
WITH RECURSIVE POST_TREE AS ( SELECT A.* FROM ( SELECT tp.BOARD_CODE, tp.POST_CODE, tp.POST_NM, tp.POST_INFO, tp.NOTICE_CHECK, tp.UPPER_CODE, tp.DETHP, tp.VIEW_COUNT, tp.SECRET_CHECK, tp.INSERT_USER_ID, tp.INSERT_DT, tp.COMMENT_CHECK, tp.ANSWER_CHECK, (SELECT COUNT(*) FROM TB_COMMENT tc WHERE tp.POST_CODE = tc.POST_CODE) AS COMMENT_CNT, TO_CHAR(tp.POST_CODE, 'FM0000000000') AS PATH, ROW_NUMBER() OVER (ORDER BY tp.POST_CODE ASC) AS RSEQ FROM TB_POST tp WHERE BOARD_CODE = #{boardCode} AND tp.UPPER_CODE = 0 AND tp.NOTICE_CHECK = 'N'
AND POST_NM LIKE '%'||#{searchValue}||'%'
AND INSERT_USER_ID LIKE '%'||#{searchValue}||'%'
AND POST_NM LIKE '%'||#{searchValue}||'%' or INSERT_USER_ID LIKE '%'||#{searchValue}||'%'
) A WHERE RSEQ > ((#{page} - 1) * #{listView}) AND RSEQ <= (#{page} * #{listView}) UNION ALL SELECT p.BOARD_CODE, p.POST_CODE, p.POST_NM, p.POST_INFO, p.NOTICE_CHECK, p.UPPER_CODE, p.DETHP, p.VIEW_COUNT, p.SECRET_CHECK, p.INSERT_USER_ID, p.INSERT_DT, p.COMMENT_CHECK, p.ANSWER_CHECK, (SELECT COUNT(*) FROM TB_COMMENT tc WHERE p.POST_CODE = tc.POST_CODE) AS COMMENT_CNT, pt.PATH || '-' || TO_CHAR(p.POST_CODE, 'FM0000000000') AS PATH, NULL AS RSEQ FROM TB_POST p JOIN POST_TREE pt ON p.UPPER_CODE = pt.POST_CODE WHERE p.BOARD_CODE = #{boardCode} ) SELECT * FROM POST_TREE WHERE 1=1 ORDER BY PATH, RSEQ ASC, INSERT_DT ASC;

mapper.update:

UPDATE TB_POST
SET
    POST_NM =  #{postNm},
    POST_INFO = #{postInfo}
   WHERE POST_CODE = #{postCode}


    UPDATE TB_COMMENT
    SET
        COMMENT_CONTENT = #{commentContent}
	WHERE COMMENT_CODE = #{commentCode}
